INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(61570, 0, 0, 'The Upper Binding begins to glow with energy.', 16, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66621'),
(61570, 1, 0, 'It is complete, the binding is energized!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66616'),
(61281, 0, 0, 'Now witness... The Eye!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66613'),
(61281, 1, 0, 'I see... Stillward as it was... the battle.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66614'),
(61281, 2, 0, 'This cannot be. A Greymane... holding such power.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66615'),
(61286, 0, 0, 'The concoction explodes violently, covering Orvan in blood.', 16, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66620'),
(61286, 1, 0, 'Damn it! We will need the blasted book after all.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66606'),
(61259, 0, 0, 'Tyranny has been defeated this day! Our land has been freed from the evil that has corrupted our forests, and murdered countless innocents. A new king has been crowned, glory to Gilneas!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66625'),
(61287, 0, 0, 'Rest easy Franklin, you will be missed.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66611'),
(61514, 0, 0, 'Another comes to bother these lands? I do not have the patience to toy with another. Join us in the cold, dead ground.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66607');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9061259, 'Gilneas has seen darker days. But with newfound allies, such as you, hope remains. I feared the Alliance would\'ve abandoned us, but here we stand. I will bend no knee to these Alteraci scum.$B$BWe will prevail.', 'Gilneas has seen darker days. But with newfound allies, such as you, hope remains. I feared the Alliance would\'ve abandoned us, but here we stand. I will bend no knee to these Alteraci scum.$B$BWe will prevail.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9061259, 9061259);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9061259, 0, 0, 'Debrief me on the situation in Gilneas.', 0, 1, 1, 9030123, 0, 0, 0, NULL, 0, 0);
INSERT INTO `conditions` (`SourceTypeOrReferenceId`, `SourceGroup`, `SourceEntry`, `SourceId`, `ElseGroup`, `ConditionTypeOrReference`, `ConditionTarget`, `ConditionValue1`, `ConditionValue2`, `ConditionValue3`, `NegativeCondition`, `ErrorType`, `ErrorTextId`, `ScriptName`, `Comment`) VALUES (15, 9061259, 0, 0, 0, 47, 0, 40972, 8, 0, 0, 0, 0, '', 'mod-turtle-content gossip option');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030123, 'I\'ll try to keep things short.$B$BGenn Greymane sought to shield Gilneas from the troubles that plagued the rest of the world. He firmly believed that we possessed the strength and resilience to stand alone, that the outside world brought nothing but strife. And for a time, it seemed he was right. Soon after the completion of the formidable Greymane Wall, the dread Scourge descended upon the North, leaving only desolation and ruins in its wake.$B$BYet, our isolated existence brought forth its own challenges. Scarce food and crippling trade restrictions plagued us. Scourge and worgen managed to find its way to our kingdom. Despite these hardships, the king remained steadfast, stubbornly refusing to open our gates and growing increasingly detached from his nobles and subjects.', 'I\'ll try to keep things short.$B$BGenn Greymane sought to shield Gilneas from the troubles that plagued the rest of the world. He firmly believed that we possessed the strength and resilience to stand alone, that the outside world brought nothing but strife. And for a time, it seemed he was right. Soon after the completion of the formidable Greymane Wall, the dread Scourge descended upon the North, leaving only desolation and ruins in its wake.$B$BYet, our isolated existence brought forth its own challenges. Scarce food and crippling trade restrictions plagued us. Scourge and worgen managed to find its way to our kingdom. Despite these hardships, the king remained steadfast, stubbornly refusing to open our gates and growing increasingly detached from his nobles and subjects.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030123, 9030123);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030123, 0, 0, '<Continue>', 0, 1, 1, 9030124, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030124, 'He grew increasingly isolated, ensconced within the confines of his own family. And then came the Harlows, Alteraci scum who had found refuge within our walls. Whispering poison into Genn\'s ears, they further isolated him from his loyal nobles and common folk.$B$BTo preserve what scarce resources remained, many nobles, including myself, had our lands and possessions seized for redistribution. It was a painful blow, for I had been a vocal opponent of the king\'s decision. Stripped of my holdings, I was left with nothing but the fire of righteous indignation burning within me.$B$BThroughout this turmoil, Genn\'s unwavering love for his wife, Mia, provided a semblance of sanity. At her behest, he emerged from seclusion, organizing a public event to distribute food and clothing to the Gilnean populace. Regrettably, the meager resources quickly dwindled, leading to a confrontation between the common folk and the guards. In the ensuing chaos, Mia tragically lost her life.', 'He grew increasingly isolated, ensconced within the confines of his own family. And then came the Harlows, Alteraci scum who had found refuge within our walls. Whispering poison into Genn\'s ears, they further isolated him from his loyal nobles and common folk.$B$BTo preserve what scarce resources remained, many nobles, including myself, had our lands and possessions seized for redistribution. It was a painful blow, for I had been a vocal opponent of the king\'s decision. Stripped of my holdings, I was left with nothing but the fire of righteous indignation burning within me.$B$BThroughout this turmoil, Genn\'s unwavering love for his wife, Mia, provided a semblance of sanity. At her behest, he emerged from seclusion, organizing a public event to distribute food and clothing to the Gilnean populace. Regrettably, the meager resources quickly dwindled, leading to a confrontation between the common folk and the guards. In the ensuing chaos, Mia tragically lost her life.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030124, 9030124);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030124, 0, 0, '<Continue>', 0, 1, 1, 9030125, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030125, 'Devastated, Genn withdrew to the confines of his mansion, retreating from public view. The Harlow family seized power as regents, ushering in a reign of tyranny over Gilneas. Falsely accused of Mia\'s murder, I had no choice but to rally the support of the commonfolk and rise up against the oppressive regime.$B$BIn my heart, I know Genn is no longer among the living. Even in his compromised state, he would never have allowed such injustices to prevail. As we forge ahead in this rebellion, we strive to restore justice and bring about the liberation of Gilneas from the clutches of tyranny.', 'Devastated, Genn withdrew to the confines of his mansion, retreating from public view. The Harlow family seized power as regents, ushering in a reign of tyranny over Gilneas. Falsely accused of Mia\'s murder, I had no choice but to rally the support of the commonfolk and rise up against the oppressive regime.$B$BIn my heart, I know Genn is no longer among the living. Even in his compromised state, he would never have allowed such injustices to prevail. As we forge ahead in this rebellion, we strive to restore justice and bring about the liberation of Gilneas from the clutches of tyranny.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030125, 9030125);
INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES (9030125, 0, 0, 'I see.', 0, 1, 1, 0, 0, 0, 0, NULL, 0, 0);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9061379, 'Well, this is a fine day here in Gilneas, isn\'t it? Take care if you leave town, alright?', 'Well, this is a fine day here in Gilneas, isn\'t it? Take care if you leave town, alright?', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9061379, 9061379);
